<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>signal / noise</title>
<style>
  :root{
    --bg-0:#0b0f14;
    --bg-1:#0e141b;
    --ink:#e8f1ff;
    --muted:#9bb0c8;
    --accent:#9ae6ff;
    --pulse:#78ffd6;
    --shadow: 0 10px 30px rgba(0,0,0,.35);
  }

  @media (prefers-color-scheme: light){
    :root{
      --bg-0:#f7fbff;
      --bg-1:#eef5ff;
      --ink:#0c1a2a;
      --muted:#3f5b77;
      --accent:#0069ff;
      --pulse:#36cfc9;
    }
  }

  * { box-sizing: border-box; }

  html, body {
    height: 100%;
    margin: 0;
    background: radial-gradient(1200px 800px at 70% 20%, var(--bg-1), var(--bg-0));
    color: var(--ink);
    font: 16px/1.5 ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial, Apple Color Emoji, Segoe UI Emoji;
    overflow: hidden; /* canvas experience */
  }

  /* Layout shell */
  .wrap{
    position: relative;
    width: 100%;
    height: 100%;
  }

  /* Constellation layer */
  canvas#sky{
    position:absolute; inset:0;
    z-index: 0;
  }

  /* Center card: a tiny island of meaning */
  .card{
    position: absolute; inset: 0;
    display: grid; place-items: center;
    pointer-events: none; /* clicks pass to canvas */
  }

  .inner{
    pointer-events:auto;
    max-width: 700px;
    margin: 0 5vw;
    padding: 22px 22px 18px;
    background: color-mix(in oklab, var(--bg-1) 80%, black 20%);
    border: 1px solid color-mix(in oklab, var(--muted) 25%, transparent);
    border-radius: 18px;
    box-shadow: var(--shadow);
    backdrop-filter: blur(4px) saturate(1.05);
  }

  .title{
    display:flex; gap:.6ch; align-items:center; flex-wrap:wrap;
    letter-spacing: .4px;
    font-weight: 700;
    text-transform: lowercase;
  }
  .dot{
    width:.65em; height:.65em; border-radius:999px;
    background: radial-gradient(circle at 35% 35%, var(--pulse), var(--accent));
    box-shadow: 0 0 12px var(--accent), 0 0 24px color-mix(in oklab, var(--accent) 50%, transparent);
    animation: breathe 3.6s ease-in-out infinite;
  }

  @keyframes breathe {
    0%,100% { transform: scale(1); filter: drop-shadow(0 0 1px var(--accent)); }
    50% { transform: scale(1.08); filter: drop-shadow(0 0 6px var(--accent)); }
  }

  .mantra{
    margin: 8px 0 10px;
    color: var(--muted);
    font-size: .95rem;
    letter-spacing:.2px;
  }

  .seed{
    margin: 10px 0 0;
    padding: 10px 12px;
    border-radius: 12px;
    background: color-mix(in oklab, var(--bg-1) 75%, black 25%);
    border: 1px dashed color-mix(in oklab, var(--muted) 35%, transparent);
    font-size: .95rem;
  }

  .keys{
    margin-top: 10px;
    display:flex; gap:10px; flex-wrap:wrap;
    font-size: .82rem; color: var(--muted);
  }
  .kbd{
    display:inline-grid; place-items:center;
    min-width: 1.7ch;
    padding: 2px 6px;
    border: 1px solid color-mix(in oklab, var(--muted) 50%, transparent);
    border-bottom-width: 2px;
    border-radius: 6px;
    background: color-mix(in oklab, var(--bg-1) 70%, black 30%);
    color: var(--ink);
    box-shadow: inset 0 -1px 0 rgba(255,255,255,.05);
    font-weight: 600; letter-spacing:.2px;
  }

  /* Quiet Mode (Q): toned-down ink & stillness */
  .quiet body, .quiet {
    filter: grayscale(.2) saturate(.8) contrast(.98);
  }
  .quiet .dot { animation: none; opacity:.7; }

  /* Respect reduced motion */
  @media (prefers-reduced-motion: reduce){
    .dot { animation:none; }
    html, body { scroll-behavior: auto; }
  }

  /* Minimal accessibility affordances */
  .sr-only{
    position:absolute; width:1px; height:1px;
    padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0);
    white-space:nowrap; border:0;
  }
</style>
</head>
<body>
<div class="wrap">
  <canvas id="sky" aria-hidden="true"></canvas>

  <div class="card" aria-live="polite">
    <div class="inner" role="group" aria-label="signal and noise">
      <div class="title">
        <span class="dot" aria-hidden="true"></span>
        <span>signal / noise</span>
      </div>
      <div class="mantra" id="mantra">
        small, steady improvements; playful rigor; kindness as default; truth with soft edges.
      </div>
      <div class="seed" id="seed" tabindex="0" aria-label="thought seed">
        hover anywhere; the stars will adjust. press <span class="kbd">N</span> for a new seed.
      </div>
      <div class="keys" aria-hidden="false">
        <div><span class="kbd">N</span> new seed</div>
        <div><span class="kbd">Q</span> quiet mode</div>
        <div><span class="kbd">G</span> gentle debug</div>
        <div><span class="kbd">Click</span> re-center</div>
      </div>
    </div>
  </div>

  <p class="sr-only" id="alt">
    Animated starfield that drifts toward your cursor. A center panel displays a short mantra
    and a rotating ‘thought seed’. Keys: N (new seed), Q (quiet mode), G (debug log), click (re-center).
  </p>
</div>

<script>
/* -------------------------------
   signal / noise — a small study
   in attention, curiosity, & calm
----------------------------------*/

// Console breadcrumbs (quiet, but present):
console.groupCollapsed("signal/noise");
console.log("• premise: curiosity + care > speed.");
console.log("• preference: playful rigor, accessible defaults.");
console.log("• habit: start small, polish edges, name things kindly.");
console.log("• toggle: press Q for quiet mode, N for a new seed, G for gentle debug.");
console.groupEnd();

// Mantra drifts between a few truthful lines
const mantras = [
  "small, steady improvements; playful rigor; kindness as default; truth with soft edges.",
  "measure twice, refactor once; name things you care about.",
  "trust the pattern; invite surprise; keep the UI humane.",
  "make the invisible visible; reduce sharp corners; breathe."
];
let mIx = 0;
setInterval(()=>{
  mIx = (mIx+1)%mantras.length;
  document.getElementById('mantra').textContent = mantras[mIx];
}, 6500);

// Thought seeds (press N)
const seeds = [
  "What gentle assumption could make this simpler?",
  "How would this feel on a tired Tuesday?",
  "If attention is a garden, what gets watered here?",
  "Which edge cases are actually main paths for someone?",
  "What can be removed without grief?",
  "Name one sharp corner and file it down.",
  "Can failure be safe and obvious?",
  "If this whispered, what would it say?"
];
const seedEl = document.getElementById('seed');
function newSeed(){
  const s = seeds[Math.floor(Math.random()*seeds.length)];
  seedEl.textContent = s;
}
newSeed();

// Keyboard & modes
let quiet = false;
window.addEventListener('keydown', (e)=>{
  if(e.key.toLowerCase()==='n'){ newSeed(); seedEl.focus(); }
  if(e.key.toLowerCase()==='q'){
    quiet = !quiet;
    document.documentElement.classList.toggle('quiet', quiet);
    console.log(quiet ? "quiet mode: on" : "quiet mode: off");
  }
  if(e.key.toLowerCase()==='g'){
    console.group("gentle debug");
    console.table({
      motion: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'reduced' : 'ok',
      quietMode: quiet,
      stars: STARS.length,
      fps: Math.round(FPS)
    });
    console.groupEnd();
  }
});

// Constellation layer
const c = document.getElementById('sky');
const ctx = c.getContext('2d', { alpha: true });
let W = c.width = window.innerWidth;
let H = c.height = window.innerHeight;
let dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
c.width = W * dpr; c.height = H * dpr; ctx.scale(dpr, dpr);

window.addEventListener('resize', ()=>{
  W = window.innerWidth; H = window.innerHeight;
  c.width = W * dpr; c.height = H * dpr; ctx.setTransform(dpr,0,0,dpr,0,0);
  // nudge center on resize to avoid odd drift
  target.x = W/2; target.y = H/2;
});

// Stars with gentle gravitation toward pointer
const STARS = [];
const COUNT = Math.min(220, Math.floor((W*H)/7000));
const target = { x: W/2, y: H/2 };
const mouse = { x: W/2, y: H/2, active: false };

function rand(a,b){ return a + Math.random()*(b-a); }

for(let i=0;i<COUNT;i++){
  STARS.push({
    x: rand(0,W),
    y: rand(0,H),
    z: rand(0.3, 1),
    vx: rand(-0.2,0.2),
    vy: rand(-0.2,0.2),
    tw: rand(0.4, 1),
  });
}

c.addEventListener('mousemove', (e)=>{
  const rect = c.getBoundingClientRect();
  mouse.x = e.clientX - rect.left;
  mouse.y = e.clientY - rect.top;
  target.x = mouse.x; target.y = mouse.y;
  mouse.active = true;
});
c.addEventListener('mouseleave', ()=>{ mouse.active = false; });
c.addEventListener('click', ()=>{
  target.x = W/2; target.y = H/2; // re-center
});

let last=0, FPS=0;
function loop(ts){
  const dt = (ts - last)/16.6667; // ~frames
  last = ts;

  // fade the sky a touch for subtle trails
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  ctx.fillRect(0,0,W,H);

  // faint gradient halo around target
  const g = ctx.createRadialGradient(target.x, target.y, 0, target.x, target.y, Math.max(W,H)/3);
  g.addColorStop(0, 'rgba(154,230,255,0.20)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(target.x, target.y, Math.max(W,H)/3, 0, Math.PI*2); ctx.fill();

  // star physics
  ctx.lineWidth = 1;
  for(const s of STARS){
    const dx = (target.x - s.x);
    const dy = (target.y - s.y);
    const dist = Math.hypot(dx, dy) + 0.0001;

    // mild gravity toward target, weaker if quiet
    const power = (quiet ? 0.003 : 0.006) * s.z;
    s.vx += (dx / dist) * power;
    s.vy += (dy / dist) * power;

    // soft drag for stability
    s.vx *= 0.985; s.vy *= 0.985;

    s.x += s.vx * dt;
    s.y += s.vy * dt;

    // wrap around edges
    if(s.x < -2) s.x = W+2;
    if(s.x > W+2) s.x = -2;
    if(s.y < -2) s.y = H+2;
    if(s.y > H+2) s.y = -2;

    // draw: point + a thread toward motion
    const alpha = 0.7 * s.z * (quiet ? 0.6 : 1);
    ctx.strokeStyle = `rgba(154,230,255,${0.25*alpha})`;
    ctx.beginPath();
    ctx.moveTo(s.x, s.y);
    ctx.lineTo(s.x - s.vx*3, s.y - s.vy*3);
    ctx.stroke();

    ctx.fillStyle = `rgba(120,255,214,${alpha})`;
    ctx.beginPath();
    ctx.arc(s.x, s.y, 0.8 + s.z, 0, Math.PI*2);
    ctx.fill();
  }

  // negligible FPS estimate for debug
  FPS = FPS*0.9 + (1000/Math.max(1, (ts - (last||ts))))*0.1;

  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// Accessibility: if reduced motion, pin target to center
if (window.matchMedia('(prefers-reduced-motion: reduce)').matches){
  target.x = W/2; target.y = H/2;
  document.getElementById('mantra').textContent =
    "low-motion mode respected; the sky keeps its gentle pace.";
}

// Subtle first-focus so keyboard users see the seed
setTimeout(()=>seedEl.focus(), 600);
</script>
</body>
</html>
